    arpeggios: ArpeggioDefinition[];
    arpBpm: number;
    onArpToggle?: (id: string) => void;
    onArpBpmChange?: (bpm: number) => void;
    onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
    onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
    recordingArpId?: string | null;
    currentArpStep?: number;
    recordingFlash?: number;
    onPlayAll?: () => void;
    onStopAll?: () => void;
    isSequencerOpen: boolean;
    onToggleSequencer: () => void;

    // UI Props
    uiScale: number;
    position: { x: number, y: number };
    isConstrained: boolean;
    width: number;
    onDragStart: (e: React.PointerEvent) => void;
    isFlashingRed: boolean;
    uiUnlocked: boolean;
}

const ArpeggiatorBar: React.FC<Props> = ({
    arpeggios, arpBpm, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate,
    recordingArpId, currentArpStep, onPlayAll, onStopAll,
    isSequencerOpen, onToggleSequencer,
    uiScale, position, isConstrained, width, onDragStart, isFlashingRed, uiUnlocked
}) => {
    const [isHovered, setIsHovered] = useState(false);

    const isAnyArpPlaying = arpeggios.some(a => a.isPlaying);

    const getBpmLightClass = () => {
        if (isFlashingRed) return 'bg-red-500 shadow-[0_0_10px_red]';
        if (isAnyArpPlaying) {
            const tick = Math.floor(Date.now() / (30000 / (arpBpm || 120)));
            return tick % 2 === 0 ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800';
        }
        return 'bg-slate-800';
    };

    const handleStepClick = (e: React.MouseEvent | React.TouchEvent, arpId: string, stepIndex: number) => {
        e.stopPropagation();
        const arp = arpeggios.find(a => a.id === arpId);
        if (!arp || !onArpPatternUpdate) return;

        if (stepIndex < arp.steps.length) {
            const step = arp.steps[stepIndex];
            const newSteps = [...arp.steps];
            newSteps[stepIndex] = { ...step, muted: !step.muted };
            onArpPatternUpdate(arpId, newSteps);
        }
    };

    const handleStepRightClick = (e: React.MouseEvent, arpId: string, stepIndex: number) => {
        e.preventDefault();
        e.stopPropagation();
        const arp = arpeggios.find(a => a.id === arpId);
        if (!arp || !onArpPatternUpdate) return;

        if (stepIndex < arp.steps.length) {
            const newSteps = [...arp.steps];
            newSteps.splice(stepIndex, 1);
            onArpPatternUpdate(arpId, newSteps);
        }
    };

    return (
        <div 
            className={`absolute bg-slate-900/50 rounded-xl flex flex-col items-center backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-2xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
            style={{ 
                left: position.x,
                top: position.y,
                width: width,
                padding: `3px ${8 * uiScale}px`,
                height: 'auto',
                touchAction: 'none'
            }}
            onPointerDown={onDragStart}
            onPointerEnter={() => setIsHovered(true)}
            onPointerLeave={() => setIsHovered(false)}
        >
            <div className="w-full flex flex-col gap-2">
                 {/* Top Row: Label + Controls (Wraps if narrow) */}
                 <div className="flex flex-wrap items-center justify-between gap-y-2 px-1">
                     <span className="text-[12px] font-bold text-slate-400 uppercase tracking-widest mr-2 flex-shrink-0">ARPEGGIATOR</span>

                     <div className="flex items-center gap-2 flex-shrink-0">
                         <div className="flex items-center bg-slate-800/50 rounded border border-slate-700/50 overflow-hidden h-5">
                            <button 
                                className="px-1.5 hover:bg-slate-700 active:bg-slate-600 text-slate-400 hover:text-white transition-colors border-r border-slate-700/30 flex items-center justify-center h-full"
                                onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.max(1, (arpBpm || 120) - 1)); }}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-2.5 w-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                            </button>
                            <input 
                                type="number" 
                                value={arpBpm} 
                                onChange={(e) => onArpBpmChange && onArpBpmChange(parseInt(e.target.value))}
                                className="w-8 bg-transparent text-center text-[10px] font-mono font-bold text-slate-300 focus:outline-none focus:text-white no-spinner h-full"
                                onPointerDown={(e) => e.stopPropagation()}
                            />
                            <button 
                                className="px-1.5 hover:bg-slate-700 active:bg-slate-600 text-slate-400 hover:text-white transition-colors border-l border-slate-700/30 flex items-center justify-center h-full"
                                onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange((arpBpm || 120) + 1); }}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-2.5 w-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                            </button>
                         </div>

                         <button 
                            className={`h-5 px-2 rounded text-[9px] font-bold uppercase transition-all flex items-center gap-1 ${isAnyArpPlaying ? 'bg-green-900/50 text-green-400 border border-green-500/30' : 'bg-slate-800 text-slate-400 border border-slate-600 hover:bg-slate-700'}`}
                            onPointerDown={(e) => { e.stopPropagation(); isAnyArpPlaying ? (onStopAll && onStopAll()) : (onPlayAll && onPlayAll()); }}
                         >
                            <div className={`w-1.5 h-1.5 rounded-full ${getBpmLightClass()}`} />
                            {isAnyArpPlaying ? 'Stop' : 'Play'}
                         </button>

                         <button
                            className={`h-5 px-2 rounded text-[9px] font-bold uppercase transition-all border ${isSequencerOpen ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-slate-600 text-slate-400 hover:bg-slate-700'}`}
                            onPointerDown={(e) => { e.stopPropagation(); onToggleSequencer(); }}
                         >
                            {isSequencerOpen ? 'Hide' : 'Edit'}
                         </button>
                     </div>
                 </div>

                 {isSequencerOpen && (
                     <div className="w-full pt-2 border-t border-slate-700/50 mt-1 animate-in slide-in-from-top-2 duration-200">
                         <div className="grid grid-cols-[auto_1fr] gap-2 max-h-[300px] overflow-y-auto pr-1 custom-scrollbar">
                             {arpeggios.map((arp) => (
                                 <React.Fragment key={arp.id}>
                                     <div className="flex flex-col items-center gap-1 py-1">
                                         <button 
                                            className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold transition-all border ${arp.isPlaying ? 'bg-green-600 border-green-500 text-white' : 'bg-slate-800 border-slate-600 text-slate-400 hover:text-white'}`}
                                            onPointerDown={(e) => { e.stopPropagation(); onArpToggle && onArpToggle(arp.id); }}
                                         >
                                             {arp.id}
                                         </button>
                                         <button
                                            className={`w-6 h-6 rounded flex items-center justify-center transition-all border ${recordingArpId === arp.id ? 'bg-red-600 border-red-500 text-white animate-pulse' : 'bg-slate-800 border-slate-600 text-slate-500 hover:text-red-400'}`}
                                            onPointerDown={(e) => { e.stopPropagation(); onArpToggle && onArpToggle(arp.id); }}
                                            title="Record Pattern"
                                         >
                                             <div className={`w-2 h-2 rounded-full ${recordingArpId === arp.id ? 'bg-white' : 'bg-current'}`} />
                                         </button>
                                     </div>

                                     <div className="flex items-center bg-slate-800/30 rounded px-1 gap-0.5 overflow-hidden h-[54px] relative">
                                         {arp.steps.length === 0 ? (
                                             <div className="w-full text-center text-[10px] text-slate-600 italic select-none">Empty Pattern</div>
                                         ) : (
                                             arp.steps.map((step, idx) => {
                                                 const isActive = arp.isPlaying && (currentArpStep !== undefined) && (currentArpStep % arp.steps.length === idx);
                                                 // Visual height based on pitch ratio approximation
                                                 const heightPct = Math.min(100, 20 + (Math.log2(step.ratio) * 30));

                                                 const limit = step.limit || 3;
                                                 const color = DEFAULT_COLORS[limit] || '#ffffff';

                                                 return (
                                                     <div 
                                                        key={idx} 
                                                        className={`flex-1 h-full min-w-[4px] relative group cursor-pointer ${step.muted ? 'opacity-30 grayscale' : 'opacity-100'}`}
                                                        style={{ backgroundColor: isActive ? 'rgba(255,255,255,0.1)' : 'transparent' }}
                                                        onPointerDown={(e) => handleStepClick(e, arp.id, idx)}
                                                        onContextMenu={(e) => handleStepRightClick(e, arp.id, idx)}
                                                     >
                                                         <div 
                                                            className={`absolute bottom-0 left-0 right-0 mx-[1px] rounded-t-sm transition-all ${isActive ? 'brightness-150' : ''}`}
                                                            style={{ 
                                                                height: `${heightPct}%`,
                                                                backgroundColor: color
                                                            }}
                                                         />
                                                     </div>
                                                 );
                                             })
                                         )}
                                     </div>
                                 </React.Fragment>
                             ))}
                         </div>
                     </div>
                 )}
            </div>
        </div>
    );
};

export default ArpeggiatorBar;
